import React from 'react';
import userEvent from '@testing-library/user-event';
import { fireEvent, render, screen } from '@testing-library/react';
import Table from './Table';
import { generatePersonMock, personColumnsMock } from './__mock';
import { HeaderAllSelectionType } from './Table.types';

const mockData = generatePersonMock(20);
const personsMock = [
  {
    name: 'Kiara',
    age: 52,
    address: '2163 Mayert Glen',
  },
  {
    name: 'John',
    age: 24,
    address: '1864 Glover Flats',
  },
  {
    name: 'Maria',
    age: 65,
    address: '182 Nash Fort',
  },
];

describe('Table', () => {
  test('should render a basic table', () => {
    render(<Table columns={personColumnsMock} data={mockData} />);
    expect(screen.getByText(mockData[0].name)).toBeInTheDocument();
  });

  test('should render a table with fixed header', () => {
    render(<Table columns={personColumnsMock} data={mockData} fixedHeader />);
    expect(screen.getByText(mockData[0].name)).toBeInTheDocument();
  });

  test('should render a table with fixed height', () => {
    render(<Table columns={personColumnsMock} data={mockData} tableHeight="300px" />);
    expect(screen.getByText(mockData[0].name)).toBeInTheDocument();
  });

  test('should render with loading state', () => {
    render(<Table columns={personColumnsMock} data={mockData} loading />);

    expect(screen.getByText('Loading items...')).toBeInTheDocument();
  });
  test('should render a table with initial value in variant search', () => {
    render(
      <Table
        columns={personColumnsMock}
        data={mockData}
        search
        initialValueSearch={mockData[0].name}
      />
    );
    expect(screen.getByText(mockData[0].name)).toBeInTheDocument();
  });

  const initialSortTestCases = [
    ['should render a table with default asc order in it', false, ['John', 'Kiara', 'Maria']],
    ['should render a table with default desc order in it', true, ['Maria', 'Kiara', 'John']],
  ];

  // eslint-disable-next-line max-params
  test.each(initialSortTestCases)('%s', (description, descValue, expected) => {
    const { container } = render(
      <Table
        columns={personColumnsMock}
        data={personsMock}
        initialSortBy={[{ id: 'name', desc: descValue as boolean }]}
      />
    );

    const tableNames: string[] = [];
    container.querySelectorAll('tbody tr > td:first-child').forEach((element: Element) => {
      tableNames.push(element.innerHTML);
    });

    expect(tableNames).toStrictEqual(expected);
  });

  test('should render with no data message when has no data passed', () => {
    render(<Table columns={personColumnsMock} data={[]} />);

    expect(screen.getByText("There's no information to show")).toBeInTheDocument();
  });

  test('should accept a custom render function inside columns array', () => {
    const columnsMock = [
      {
        Header: 'Name',
        accessor: 'name',
        style: {
          minWidth: '200px',
        },
        customRender: (value: unknown) => `The person's name is ${value}`,
      },
      {
        Header: 'Age',
        accessor: 'age',
        style: {
          minWidth: '200px',
        },
        disableSortBy: true,
      },
      {
        Header: 'Address',
        accessor: 'address',
        style: {
          minWidth: '200px',
        },
      },
    ];
    render(<Table columns={columnsMock} data={mockData} />);

    expect(screen.getByText(`The person's name is ${mockData[0].name}`)).toBeInTheDocument();
  });

  test('should be able to sort a column with sort feature on', async () => {
    const user = userEvent.setup();
    const columnsMock = [
      {
        Header: 'Name',
        accessor: 'name',
        style: {
          minWidth: '200px',
        },
      },
      {
        Header: 'Age',
        accessor: 'age',
        style: {
          minWidth: '200px',
        },
        disableSortBy: true,
      },
      {
        Header: 'Address',
        accessor: 'address',
        style: {
          minWidth: '200px',
        },
      },
    ];
    const mockOnSort = jest.fn();
    render(<Table columns={columnsMock} data={mockData} onSort={mockOnSort} />);

    const nameColumn = screen.getByText('Name');
    await user.click(nameColumn);

    expect(mockOnSort).toHaveBeenCalledWith('name', 'ASC');

    await user.click(nameColumn);
    expect(mockOnSort).toHaveBeenCalledWith('name', 'DESC');
  });

  test('should not be able to sort a column when sort feature is disabled in columns config', async () => {
    const user = userEvent.setup();
    const mockOnSort = jest.fn();
    const columnsMock = [
      {
        Header: 'Name',
        accessor: 'name',
        style: {
          minWidth: '200px',
        },
      },
      {
        Header: 'Age',
        accessor: 'age',
        style: {
          minWidth: '200px',
        },
        disableSortBy: true,
      },
      {
        Header: 'Address',
        accessor: 'address',
        style: {
          minWidth: '200px',
        },
      },
    ];
    render(<Table columns={columnsMock} data={mockData} onSort={mockOnSort} />);

    const ageColumn = screen.getByText('Age');
    await user.click(ageColumn);

    expect(mockOnSort).not.toHaveBeenCalled();
  });

  describe('Pagination', () => {
    test('should show no pagination when pagination is set to false', () => {
      render(<Table columns={personColumnsMock} data={mockData} pagination={false} />);
      expect(screen.queryByText('1-10 of 20')).not.toBeInTheDocument();
    });

    test('should be able to navigate between pages when it has pagination on', async () => {
      const user = userEvent.setup();
      render(<Table columns={personColumnsMock} data={mockData} />);

      await user.click(screen.getAllByTitle('next page')[1]);

      expect(screen.getByText(mockData[15].address)).toBeInTheDocument();
    });

    test('should render with controlled pagination', async () => {
      const user = userEvent.setup();
      const mockPaginationOnChange = jest.fn();

      render(
        <Table
          columns={personColumnsMock}
          data={mockData}
          pagination={{
            total: 200,
            pageSize: 25,
            current: 1,
            onChange: mockPaginationOnChange,
          }}
        />
      );

      await user.click(screen.getAllByTitle('next page')[1]);

      expect(mockPaginationOnChange).toHaveBeenCalledWith(2, 25);
    });
  });

  describe('Expandable rows', () => {
    test('should render a table with expandable rows', async () => {
      const user = userEvent.setup();
      render(
        <Table
          columns={personColumnsMock}
          data={personsMock}
          tableHeight="300px"
          expandable={{
            rowHasExpandFeature: (data) => data.age > 50,
            render: (data) => (
              <div>
                <div>{`${data.name} has lived over half a century, having the age of ${data.age}!`}</div>
              </div>
            ),
          }}
        />
      );
      const a = screen.getByText('2163 Mayert Glen');
      await user.click(a.parentElement as HTMLTableRowElement);
      expect(screen.getByText(/Kiara has lived over half a century/)).toBeInTheDocument();
    });

    test('should not render expandable rows when expanded condition evaluates to false', async () => {
      const user = userEvent.setup();
      render(
        <Table
          columns={personColumnsMock}
          data={personsMock}
          tableHeight="300px"
          expandable={{
            rowHasExpandFeature: (data) => data.age > 50,
            render: (data) => (
              <div>
                <div>{`${data.name} has lived over half a century, having the age of ${data.age}!`}</div>
              </div>
            ),
          }}
        />
      );
      const a = screen.getByText('1864 Glover Flats');
      await user.click(a.parentElement as HTMLTableRowElement);
      expect(screen.queryByText(/John has lived over half a century/)).not.toBeInTheDocument();
    });

    test('should be able to search when the search prop is true', async () => {
      const user = userEvent.setup();
      render(<Table columns={personColumnsMock} data={personsMock} tableHeight="300px" search />);
      const searchInput = screen.getByPlaceholderText('Search');
      await user.type(searchInput, 'John');
      expect(screen.queryByText(/Maria/)).not.toBeInTheDocument();
      expect(screen.queryByText(/John/)).toBeInTheDocument();
    });

    test('should be able to clear the search by clicking the clear button', async () => {
      const user = userEvent.setup();
      const { container } = render(
        <Table columns={personColumnsMock} data={personsMock} tableHeight="300px" search />
      );
      const searchInput = screen.getByPlaceholderText('Search');
      await user.type(searchInput, 'John');
      expect(screen.queryByText(/Maria/)).not.toBeInTheDocument();
      expect(screen.queryByText(/John/)).toBeInTheDocument();

      await user.click(container.querySelector('[aria-label="Clear input"]'));
      expect(screen.queryByText(/Maria/)).toBeInTheDocument();
      expect(screen.queryByText(/John/)).toBeInTheDocument();
    });

    test('should call onSearch when search and onSearchChange are passed as props', async () => {
      const user = userEvent.setup();
      const mockOnChange = jest.fn();
      render(
        <Table
          columns={personColumnsMock}
          data={personsMock}
          tableHeight="300px"
          search
          onSearchChange={mockOnChange}
        />
      );
      const searchInput = screen.getByPlaceholderText('Search');
      await user.type(searchInput, 'John');
      expect(mockOnChange).toHaveBeenCalledWith('John');
    });

    test('should call onSearch when search and onSearchChange are passed as props and user clicks in the clear button', async () => {
      const user = userEvent.setup();
      const mockOnChange = jest.fn();
      const { container } = render(
        <Table
          columns={personColumnsMock}
          data={personsMock}
          tableHeight="300px"
          search
          onSearchChange={mockOnChange}
        />
      );
      const searchInput = screen.getByPlaceholderText('Search');
      await user.type(searchInput, 'John');
      await user.click(container.querySelector('[aria-label="Clear input"]'));
      expect(mockOnChange).toHaveBeenCalledWith('');
    });

    test('should render toolbar extra items when toolbarExtra props is passed', () => {
      render(
        <Table
          columns={personColumnsMock}
          data={personsMock}
          tableHeight="300px"
          toolbarExtra={({ allColumns }) => allColumns.map((column) => `Show/Hide ${column.id}`)}
        />
      );
      expect(screen.getByText(/Show\/Hide address/)).toBeInTheDocument();
    });

    test('should be able to pass a onRow prop with event callbacks', async () => {
      const user = userEvent.setup();
      const mockOnClick = jest.fn();
      const onRow = () => ({
        onClick: mockOnClick,
      });

      render(<Table columns={personColumnsMock} data={personsMock} onRow={onRow} />);
      await user.click(screen.getByText(/Maria/));
      expect(mockOnClick).toHaveBeenCalled();
    });

    test('should be shown the checkbox on the header column when the selectable.useCheckbox is passed as true', () => {
      render(
        <Table selectable={{ useCheckbox: true }} columns={personColumnsMock} data={personsMock} />
      );
      expect(screen.getByTestId('checkbox-header')).toBeInTheDocument();
    });

    test("should be don't show the checkbox on the header column when the selectable.useCheckbox is not passed", () => {
      render(<Table selectable={{}} columns={personColumnsMock} data={personsMock} />);
      expect(screen.queryByTestId('checkbox-header')).toBeNull();
    });

    test("should be showed the text '1 selected' when one checkbox is selected", () => {
      render(
        <Table selectable={{ useCheckbox: true }} columns={personColumnsMock} data={personsMock} />
      );
      const selectableActionToolbarContainer = screen.getByTestId('table-toolbar');
      fireEvent.click(screen.queryAllByRole('checkbox')[1]);
      expect(selectableActionToolbarContainer.textContent).toContain('1 selected');
    });

    test("should display content of 'selectable.displayTextDeselectAll' when attibute is passed", () => {
      render(
        <Table
          selectable={{ useCheckbox: true, displayTextDeselectAll: 'deselect_all_text' }}
          columns={personColumnsMock}
          data={personsMock}
        />
      );
      const selectableActionToolbarContainer = screen.getByTestId('table-toolbar');
      fireEvent.click(screen.queryAllByRole('checkbox')[1]);
      expect(selectableActionToolbarContainer.textContent).toContain('deselect_all_text');
    });

    test("should display content of 'selectable.counter' regardless checkbox selected by click", () => {
      render(
        <Table
          selectable={{ useCheckbox: true, counter: 3 }}
          columns={personColumnsMock}
          data={personsMock}
        />
      );
      const selectableActionToolbarContainer = screen.getByTestId('table-toolbar');
      fireEvent.click(screen.queryAllByRole('checkbox')[1]);
      expect(selectableActionToolbarContainer.textContent).toContain('3 selecteds');
    });

    test("should display content of 'selectable.counter' regardless checkbox selected by initial state", () => {
      render(
        <Table
          selectable={{ useCheckbox: true, counter: 3, initialSelectedState: { 1: true } }}
          columns={personColumnsMock}
          data={personsMock}
        />
      );
      const selectableActionToolbarContainer = screen.getByTestId('table-toolbar');
      expect(selectableActionToolbarContainer.textContent).toContain('3 selecteds');
    });

    test("should display content of 'selectable.counter' regardless of no checkbox selected", () => {
      render(
        <Table
          selectable={{ useCheckbox: true, counter: 3 }}
          columns={personColumnsMock}
          data={personsMock}
        />
      );
      const selectableActionToolbarContainer = screen.getByTestId('table-toolbar');
      expect(selectableActionToolbarContainer.textContent).toContain('3 selecteds');
    });

    test("should display selectable toolbar empty when 'selectable.counter' is zero", () => {
      render(
        <Table
          selectable={{ useCheckbox: true, counter: 0 }}
          columns={personColumnsMock}
          data={personsMock}
        />
      );
      const selectableActionToolbarContainer = screen.getByTestId('table-toolbar');
      expect(selectableActionToolbarContainer.textContent).toStrictEqual('');
    });

    test("should ignore selected items when 'selectable.counter' is zero", () => {
      render(
        <Table
          selectable={{ useCheckbox: true, counter: 0, initialSelectedState: { 1: true } }}
          columns={personColumnsMock}
          data={personsMock}
        />
      );
      const selectableActionToolbarContainer = screen.getByTestId('table-toolbar');
      expect(selectableActionToolbarContainer.textContent).toStrictEqual('');
    });

    test("should count selected items when 'selectable.counter' is undefined", () => {
      render(
        <Table
          selectable={{ useCheckbox: true, counter: undefined, initialSelectedState: { 1: true } }}
          columns={personColumnsMock}
          data={personsMock}
        />
      );
      const selectableActionToolbarContainer = screen.getByTestId('table-toolbar');
      expect(selectableActionToolbarContainer.textContent).toContain('1 selected');
    });

    test("should display default text 'Deselect All' when custom text is not defined", () => {
      render(
        <Table
          selectable={{ useCheckbox: true, initialSelectedState: { 0: true } }}
          columns={personColumnsMock}
          data={personsMock}
        />
      );
      const selectableActionToolbarContainer = screen.getByTestId('table-toolbar');
      expect(selectableActionToolbarContainer.textContent).toContain('Deselect All');
    });

    test('should not conflict checkbox click with onRow click', () => {
      const mockOnRowClick = jest.fn();
      const onRow = () => ({
        onClick: mockOnRowClick,
      });

      render(
        <Table
          onRow={onRow}
          selectable={{ useCheckbox: true }}
          columns={personColumnsMock}
          data={personsMock}
        />
      );
      const selectableActionToolbarContainer = screen.getByTestId('table-toolbar');
      fireEvent.click(screen.queryAllByRole('checkbox')[1]);
      expect(mockOnRowClick).not.toHaveBeenCalled();
      expect(selectableActionToolbarContainer.textContent).toContain('1 selected');

      fireEvent.click(screen.getByText(/Maria/));
      expect(mockOnRowClick).toHaveBeenCalledTimes(1);
      expect(selectableActionToolbarContainer.textContent).toContain('1 selected');
    });

    const headerCheckboxClickCases = [
      [
        '1 selected',
        HeaderAllSelectionType[HeaderAllSelectionType.ALL_PAGE_ROWS],
        HeaderAllSelectionType.ALL_PAGE_ROWS,
        {},
      ],
      [
        '3 selected',
        HeaderAllSelectionType[HeaderAllSelectionType.ALL_ROWS],
        HeaderAllSelectionType.ALL_ROWS,
        {},
      ],
      [
        '1 item selected',
        HeaderAllSelectionType[HeaderAllSelectionType.ALL_PAGE_ROWS],
        HeaderAllSelectionType.ALL_PAGE_ROWS,
        {
          displayTextOneRowSelected: 'item selected',
          displayTextMoreThanOneRowSelected: 'items selected',
        },
      ],
      [
        '3 items selected',
        HeaderAllSelectionType[HeaderAllSelectionType.ALL_ROWS],
        HeaderAllSelectionType.ALL_ROWS,
        {
          displayTextOneRowSelected: 'item selected',
          displayTextMoreThanOneRowSelected: 'items selected',
        },
      ],
    ];

    test.each(headerCheckboxClickCases)(
      `shoud be showed the text %p when the checkbox header is clicked with one element per page and the selected.headerSelectionType is %p`,
      // eslint-disable-next-line max-params
      (resultExpected, headerSelectionTypeName, headerSelectionType, customToolbarTextConfig) => {
        const mockPaginationOnChange = jest.fn();
        render(
          <Table
            pagination={{
              pageSize: 1,
              current: 1,
              onChange: mockPaginationOnChange,
            }}
            selectable={{
              ...(customToolbarTextConfig as object),
              useCheckbox: true,
              headerSelectionType: headerSelectionType as HeaderAllSelectionType,
            }}
            columns={personColumnsMock}
            data={personsMock}
          />
        );
        const selectableActionToolbarContainer = screen.getByTestId('table-toolbar');
        fireEvent.click(screen.queryAllByRole('checkbox')[0]);
        expect(selectableActionToolbarContainer.textContent).toContain(resultExpected);
      }
    );
  });
});
